INSERT INTO vehicle_history_reports ("id", "vehicle_id", "checks_json", "overall_confidence", "summary_en", "summary_km", "limitations_json", "status", "requested_by", "created_at") VALUES ('cmvnqjkud003am6ut32nu7jhx', 'veh_prado_2018', '[{"area":"identity","title":"VIN & identity","titleKm":"អត្តសញ្ញាណ និងលេខសំគាល់","status":"NOT_VERIFIED","detail":"Chassis ending T8H229 provided in the listing matches the registration book images, but the vehicle has not been physically inspected by the platform, so identity is not independently confirmed.","detailKm":"លេខចាប់ចុង T8H229 ក្នុងបញ្ជីលក់ត្រូវគ្នានឹងរូបសៀវភៅចុះបញ្ជី ប៉ុន្តែវេទិកាមិនបានពិនិត្យរថយន្តដោយផ្ទាល់ទេ ដូច្នេះអត្តសញ្ញាណមិនអាចបញ្ជាក់ដោយឯករាជ្យបានទេ។","source":"Listing data + Registration book (platform-verified)","confidence":0.6},{"area":"registration","title":"Registration book","titleKm":"សៀវភៅចុះបញ្ជី","status":"VERIFIED","detail":"Registration book reviewed and platform-verified. Plate 1KH-8823 and owner details are internally consistent.","detailKm":"សៀវភៅចុះបញ្ជីត្រូវបានពិនិត្យនិងផ្ទៀងផ្ទាត់ដោយវេទិកា។ ស្លាកលេខ 1KH-8823 និងព័ត៌មានម្ចាស់ត្រូវគ្នា។","source":"Registration book (platform-verified)","confidence":0.95},{"area":"import","title":"Import origin","titleKm":"ប្រភពនាំចូល","status":"VERIFIED","detail":"Import declaration from Dubai was verified and matches the declared import origin.","detailKm":"លិខិតប្រកាសនាំចូលពីឌូបាយត្រូវបានផ្ទៀងផ្ទាត់ ដែលត្រូវនឹងប្រភពនាំចូលដែលបានប្រកាស។","source":"Import declaration (platform-verified)","confidence":0.9},{"area":"mileage","title":"Odometer & mileage","titleKm":"ចំនួនគីឡូម៉ែត្រ","status":"EVIDENCE_FOUND","detail":"Odometer of 89,000 km is plausible for a 2018 vehicle (about 11,100 km/year) and is consistent with service records covering 2019-2024. No independent odometer database check was possible.","detailKm":"៨៩,០០០ គ.ម មានភាពសមរម្យសម្រាប់ឡានឆ្នាំ២០១៨ (~១១,១០០ គ.ម/ឆ្នាំ) និងត្រូវគ្នានឹងកំណត់ហេតុសេវាកម្ម ២០១៩–២០២៤ ទោះបីគ្មានការពិនិត្យទិន្នន័យ odometer ដោយឯករាជ្យក៏ដោយ។","source":"Service records + Listing data","confidence":0.8},{"area":"price","title":"Price vs market","titleKm":"តម្លៃធៀបទីផ្សារ","status":"EVIDENCE_FOUND","detail":"$52,500 sits within the typical range for 2018 Prado TX diesel units in Phnom Penh ($48,000-$57,000 based on current comparable listings).","detailKm":"៥២,៥០០ ដុល្លាស្ថិតក្នុងជួរតម្លៃទីផ្សារសម្រាប់ Prado TX ស្លាបប្រេងសាឺតឆ្នាំ២០១៨ នៅភ្នំពេញ (៤៨,០០០–៥៧,០០០ ដុល្លាតាមបញ្ជីប្រៀបធៀប)។","source":"Market comparables","confidence":0.8},{"area":"service","title":"Service history","titleKm":"ប្រវត្តិថែទាំ","status":"EVIDENCE_FOUND","detail":"Authorized workshop service records covering 2019-2024 were provided and show regular maintenance.","detailKm":"កំណត់ហេតុសេវាកម្មពីរោងចក្រផ្លូវការឆ្នាំ ២០១៩–២០២៤ ត្រូវបានផ្ដល់ជូន ហើយបង្ហាញការថែទាំទាន់ពេល។","source":"Service records (provided)","confidence":0.8},{"area":"photos","title":"Photos vs description","titleKm":"រូបភាពធៀបការប្រកាស","status":"EVIDENCE_FOUND","detail":"Listing photos are consistent with the described condition (new tires, clean interior); no visible mismatch with the declared color or trim.","detailKm":"រូបភាពត្រូវគ្នានឹងការប្រកាស (កង់ថ្មី ខាងក្នុងស្អាត) ហើយគ្មានភាពមិនត្រូវគ្នាជាមួយពណ៌ ឬកម្រិតបរិក្ខារ។","source":"Listing photo analysis","confidence":0.75},{"area":"ownership","title":"Ownership history","titleKm":"ប្រវត្តិម្ចាស់ភាព","status":"EVIDENCE_FOUND","detail":"Registration book shows 2 registered owners, consistent with the seller''s declared ownership count.","detailKm":"សៀវភៅចុះបញ្ជីបង្ហាញម្ចាស់ចំនួន ២ នាក់ ត្រូវនឹងចំនួនដែលអ្នកលក់ប្រកាស។","source":"Registration book (platform-verified)","confidence":0.85},{"area":"accident","title":"Accident records","titleKm":"កំណត់ហេតុគ្រោះថ្នាក់","status":"NOT_VERIFIED","detail":"Seller declares no accidents. This is a declaration only — it is not independent verification, and no official accident database was checked.","detailKm":"អ្នកលក់ប្រកាសថាគ្មានគ្រោះថ្នាក់ចរាចរ។ នេះជាការប្រកាសតែប៉ុណ្ណោះ — មិនមែនជាការផ្ទៀងផ្ទាត់ដោយឯករាជ្យ ហើយគ្មានមូលដ្ឋានទិន្នន័យគ្រោះថ្នាក់ផ្លូវការណ៍ណាមួយត្រូវបានពិនិត្យទេ។","source":"Seller declaration","confidence":0.45},{"area":"listing","title":"Listing quality & safety","titleKm":"គុណភាពបញ្ជី និងសុវត្ថិភាព","status":"EVIDENCE_FOUND","detail":"Listing text is detailed and consistent across fields (year, mileage, documents). No scam-pattern language detected.","detailKm":"អត្ថបទបញ្ជីលក់មានព័ត៌មានលម្អិត និងត្រូវគ្នារវាងវាលនីមួយៗ (ឆ្នាំ គ.ម ឯកសារ)។ រកមិនឃើញលក្ខណៈសញ្ញានៃការបញ្ឆោតទេ។","source":"Listing text analysis","confidence":0.85}]', 78.0, 'This 2018 Prado TX presents well: the registration book and Dubai import declaration are platform-verified, and service records from 2019-2024 support the 89,000 km odometer. The seller declares no accidents, but that remains an unverified declaration. Overall the listing is consistent and transparent for its class.', 'ឡាន Prado TX ឆ្នាំ២០១៨ នេះមានលក្ខណៈល្អ៖ សៀវភៅចុះបញ្ជី និងលិខិតប្រកាសនាំចូលពីឌូបាយ ត្រូវបានផ្ទៀងផ្ទាត់ដោយវេទិកាហើយ ហើយកំណត់ហេតុសេវាកម្មឆ្នាំ២០១៩–២០២៤ គាំទ្រចំនួន ៨៩,០០០ គ.ម។ អ្នកលក់ប្រកាសថាគ្មានគ្រោះថ្នាក់ចរាចរ ប៉ុន្តែការប្រកាសនេះមិនទាន់បានផ្ទៀងផ្ទាត់ដោយឯករាជ្យទេ។ ជារួម បញ្ជីលក់នេះមានភាពទៀងទាត់ និងគួរឱ្យទុកចិត្ត។', '[{"en":"This report analyzes listing information and provided documents only. It is not a physical inspection.","km":"របាយការណ៍នេះវិភាគតែពីព័ត៌មានបញ្ជាក់ និងឯកសារដែលផ្ដល់ជូនប៉ុណ្ណោះ។ វាមិនមែនជាការពិនិត្យរថយន្តដោយផ្ទាល់ទេ។"},{"en":"''No records found'' does not mean ''no accidents'' or ''no problems''.","km":"''រកមិនឃើញទិន្នន័យ'' មិនមែនមានន័យថា ''គ្មានគ្រោះថ្នាក់'' ឬ ''គ្មានបញ្ហា'' ទេ។"},{"en":"AI observations are probabilistic and may be wrong. Always inspect the vehicle in person.","km":"ការវិភាគដោយ AI អាចមានកំហុស។ សូមពិនិត្យរថយន្តដោយខ្លួនឯងជានិច្ច។"},{"en":"Report results reflect the data available at generation time and may become outdated.","km":"លទ្ធផលរបាយការណ៍ឆ្លុះបញ្ចាំងតែទិន្នន័យនៅពេលបង្កើតប៉ុណ្ណោះ ហើយអាចមិនទាន់សម័យនៅពេលក្រោយ។"}]', 'COMPLETE', NULL, to_timestamp(1792840768068 / 1000.0)) ON CONFLICT (id) DO UPDATE SET "vehicle_id" = EXCLUDED."vehicle_id", "checks_json" = EXCLUDED."checks_json", "overall_confidence" = EXCLUDED."overall_confidence", "summary_en" = EXCLUDED."summary_en", "summary_km" = EXCLUDED."summary_km", "limitations_json" = EXCLUDED."limitations_json", "status" = EXCLUDED."status", "requested_by" = EXCLUDED."requested_by", "created_at" = EXCLUDED."created_at";
INSERT INTO vehicle_history_reports ("id", "vehicle_id", "checks_json", "overall_confidence", "summary_en", "summary_km", "limitations_json", "status", "requested_by", "created_at") VALUES ('cmvnqjkue003cm6utl9lrzlku', 'veh_lexus_rx350', '[{"area":"identity","title":"VIN & identity","titleKm":"អត្តសញ្ញាណ និងលេខសំគាល់","status":"NOT_VERIFIED","detail":"Chassis ending 5T4119 from the listing could not be cross-checked against a physical inspection or an independent VIN database.","detailKm":"លេខចាប់ចុង 5T4119 ពីបញ្ជីលក់មិនអាចផ្ទៀងផ្ទាត់ជាមួយការពិនិត្យដោយផ្ទាល់ ឬមូលដ្ឋានទិន្នន័យ VIN ឯករាជ្យបានទេ។","source":"Listing data","confidence":0.45},{"area":"registration","title":"Registration book","titleKm":"សៀវភៅចុះបញ្ជី","status":"EVIDENCE_FOUND","detail":"Registration book was provided and reviewed. Plate 2AB-1194 and the 3-owner history look consistent. Provided documents are reviewed but not platform-verified.","detailKm":"សៀវភៅចុះបញ្ជីត្រូវបានផ្ដល់ជូននិងបានពិនិត្យ។ ស្លាកលេខ 2AB-1194 និងប្រវត្តិម្ចាស់ ៣ នាក់មើលទៅត្រូវគ្នា។ ឯកសារដែលផ្ដល់ជូនត្រូវបានពិនិត្យ ប៉ុន្តែមិនត្រូវបានផ្ទៀងផ្ទាត់ដោយវេទិកាទេ។","source":"Registration book (provided)","confidence":0.7},{"area":"import","title":"Import origin","titleKm":"ប្រភពនាំចូល","status":"EVIDENCE_FOUND","detail":"US import declaration was provided; the declared USA origin is consistent with a left-hand-drive RX 350.","detailKm":"លិខិតប្រកាសនាំចូលពីអាមេរិកត្រូវបានផ្ដល់ជូន ហើយប្រភព USA ត្រូវគ្នានឹង RX 350 ចង្កឹះឆ្វេង។","source":"Import declaration (provided)","confidence":0.7},{"area":"mileage","title":"Odometer & mileage","titleKm":"ចំនួនគីឡូម៉ែត្រ","status":"NOT_VERIFIED","detail":"118,000 km over about 9 years (~13,100 km/year) is on the higher side for Phnom Penh but plausible. No odometer history database was available to rule out rollbacks.","detailKm":"១១៨,០០០ គ.ម ក្នុងរយៈពេល ~៩ ឆ្នាំ (~១៣,១០០ គ.ម/ឆ្នាំ) ខ្ពស់បន្តិចសម្រាប់ភ្នំពេញ ប៉ុន្តែមានភាពអាចកើតមាន។ គ្មានទិន្នន័យ odometer ឯករាជ្យដើម្បីបញ្ជាក់ថាគ្មានការកែចំនួនគ.មទេ។","source":"Listing data","confidence":0.5},{"area":"price","title":"Price vs market","titleKm":"តម្លៃធៀបទីផ្សារ","status":"EVIDENCE_FOUND","detail":"$34,900 is within the typical market band for 2015 RX 350 imports in Phnom Penh ($32,000-$38,000).","detailKm":"៣៤,៩០០ ដុល្លាស្ថិតក្នុងជួរទីផ្សារសម្រាប់ RX 350 ឆ្នាំ២០១៥ នៅភ្នំពេញ (៣២,០០០–៣៨,០០០ ដុល្លា)។","source":"Market comparables","confidence":0.75},{"area":"service","title":"Service history","titleKm":"ប្រវត្តិថែទាំ","status":"NO_DATA","detail":"No service records were provided, so maintenance history could not be assessed. Missing records are common but reduce transparency.","detailKm":"គ្មានកំណត់ហេតុសេវាកម្មត្រូវបានផ្ដល់ជូន ដូច្នេះប្រវត្តិថែទាំមិនអាចវាយតម្លៃបានទេ។ ការបាត់បង់កំណត់ហេតុគឺធម្មតា ប៉ុន្តែកាត់បន្ថយភាពច្បាស់លាស់។","source":"No documents provided","confidence":0.3},{"area":"photos","title":"Photos vs description","titleKm":"រូបភាពធៀបការប្រកាស","status":"EVIDENCE_FOUND","detail":"Photos show the described leather and navigation in good condition; the rear bumper appears repaired, consistent with the declared minor damage.","detailKm":"រូបភាពបង្ហាញស្បែក និងប្រព័ន្ធនាវាចរណ៍ក្នុងស្ថានភាពល្អដូចការប្រកាស។ ស្ពានក្រោយដែលបានជួសជុលត្រូវគ្នានឹងការប្រកាស។","source":"Listing photo analysis","confidence":0.65},{"area":"ownership","title":"Ownership history","titleKm":"ប្រវត្តិម្ចាស់ភាព","status":"EVIDENCE_FOUND","detail":"Registration book indicates 3 owners, matching the declared ownership count of 3.","detailKm":"សៀវភៅចុះបញ្ជីបង្ហាញម្ចាស់ ៣ នាក់ ត្រូវនឹងចំនួនដែលបានប្រកាស។","source":"Registration book (provided)","confidence":0.75},{"area":"accident","title":"Accident records","titleKm":"កំណត់ហេតុគ្រោះថ្នាក់","status":"EVIDENCE_FOUND","detail":"Seller declares minor rear-bumper damage; ask for repair documentation. Photos are consistent with a repaired bumper, but severity cannot be confirmed from the listing alone.","detailKm":"អ្នកលក់ប្រកាសថាមានគ្រោះថ្នាក់តូចនៅស្ពានក្រោយ។ សូមសុំឯកសារជួសជុល។ រូបភាពត្រូវគ្នានឹងស្ពានដែលបានជួសជុល ប៉ុន្តែកម្រិតខាតបង់មិនអាចបញ្ជាក់ពីបញ្ជីតែមួយបានទេ។","source":"Seller declaration + Listing photos","confidence":0.6},{"area":"listing","title":"Listing quality & safety","titleKm":"គុណភាពបញ្ជី និងសុវត្ថិភាព","status":"EVIDENCE_FOUND","detail":"Listing is complete and honest about prior damage, a positive trust signal. No scam-pattern language detected.","detailKm":"បញ្ជីលក់ពេញលេញ និងត្រង់នៃការប្រកាសគ្រោះថ្នាក់ពីមុន ដែលជាសញ្ញាវិជ្ជមាន។ រកមិនឃើញលក្ខណៈសញ្ញាបញ្ឆោតទេ។","source":"Listing text analysis","confidence":0.75}]', 62.0, 'This 2015 RX 350 is honestly listed: the seller openly declares minor rear-bumper damage and provides registration and import documents that match the declared 3-owner history. However, the mileage could not be independently verified and no service records exist. A pre-purchase inspection with a trusted mechanic is strongly recommended.', 'ឡាន RX 350 ឆ្នាំ២០១៥ នេះត្រូវបានប្រកាសដោយត្រង់៖ អ្នកលក់ប្រកាសចំហថាមានគ្រោះថ្នាក់តូចនៅស្ពានក្រោយ ហើយផ្ដល់ឯកសារចុះបញ្ជី និងនាំចូល ដែលត្រូវគ្នានឹងម្ចាស់ចំនួន ៣ នាក់។ ទោះជាយ៉ាងណា ចំនួនគ.មមិនអាចផ្ទៀងផ្ទាត់ដោយឯករាជ្យបានទេ ហើយគ្មានកំណត់ហេតុសេវាកម្មទេ។ សូមពិនិត្យឡានជាមួយគ្រូបង្គោលមុនពេលទិញ។', '[{"en":"This report analyzes listing information and provided documents only. It is not a physical inspection.","km":"របាយការណ៍នេះវិភាគតែពីព័ត៌មានបញ្ជាក់ និងឯកសារដែលផ្ដល់ជូនប៉ុណ្ណោះ។ វាមិនមែនជាការពិនិត្យរថយន្តដោយផ្ទាល់ទេ។"},{"en":"''No records found'' does not mean ''no accidents'' or ''no problems''.","km":"''រកមិនឃើញទិន្នន័យ'' មិនមែនមានន័យថា ''គ្មានគ្រោះថ្នាក់'' ឬ ''គ្មានបញ្ហា'' ទេ។"},{"en":"AI observations are probabilistic and may be wrong. Always inspect the vehicle in person.","km":"ការវិភាគដោយ AI អាចមានកំហុស។ សូមពិនិត្យរថយន្តដោយខ្លួនឯងជានិច្ច។"},{"en":"Report results reflect the data available at generation time and may become outdated.","km":"លទ្ធផលរបាយការណ៍ឆ្លុះបញ្ចាំងតែទិន្នន័យនៅពេលបង្កើតប៉ុណ្ណោះ ហើយអាចមិនទាន់សម័យនៅពេលក្រោយ។"}]', 'COMPLETE', NULL, to_timestamp(1792840768069 / 1000.0)) ON CONFLICT (id) DO UPDATE SET "vehicle_id" = EXCLUDED."vehicle_id", "checks_json" = EXCLUDED."checks_json", "overall_confidence" = EXCLUDED."overall_confidence", "summary_en" = EXCLUDED."summary_en", "summary_km" = EXCLUDED."summary_km", "limitations_json" = EXCLUDED."limitations_json", "status" = EXCLUDED."status", "requested_by" = EXCLUDED."requested_by", "created_at" = EXCLUDED."created_at";
INSERT INTO vehicle_history_reports ("id", "vehicle_id", "checks_json", "overall_confidence", "summary_en", "summary_km", "limitations_json", "status", "requested_by", "created_at") VALUES ('cmvnqjkuf003em6ut150j7e99', 'veh_honda_dream_2023', '[{"area":"identity","title":"VIN & identity","titleKm":"អត្តសញ្ញាណ និងលេខសំគាល់","status":"VERIFIED","detail":"Plate 1KB-8899 and 125cc engine identifiers match the verified Honda registration card.","detailKm":"ស្លាកលេខ 1KB-8899 និងកម្លាំងម៉ាស៊ីន 125cc ត្រូវគ្នានឹងកាតគ្រីម៉ូតូដែលបានផ្ទៀងផ្ទាត់។","source":"Motorcycle registration card (platform-verified)","confidence":0.95},{"area":"registration","title":"Registration book","titleKm":"សៀវភៅចុះបញ្ជី","status":"VERIFIED","detail":"Motorcycle registration card (កាតគ្រី) platform-verified. Owner and plate numbers match.","detailKm":"កាតគ្រីម៉ូតូត្រូវបានផ្ទៀងផ្ទាត់ដោយវេទិកា។ ស្លាកលេខ និងឈ្មោះម្ចាស់ត្រូវគ្នា។","source":"Motorcycle card (platform-verified)","confidence":0.95},{"area":"import","title":"Import origin","titleKm":"ប្រភពនាំចូល","status":"EVIDENCE_FOUND","detail":"Official NCX Cambodia distribution assembly with genuine tax stamp.","detailKm":"ម៉ូតូដំឡើងនិងចែកចាយផ្លូវការដោយ NCX កម្ពុជា មានតែមពន្ធត្រឹមត្រូវ។","source":"NCX distribution records","confidence":0.85},{"area":"mileage","title":"Odometer & mileage","titleKm":"ចំនួនគីឡូម៉ែត្រ","status":"EVIDENCE_FOUND","detail":"3,200 km over 2 years (~1,600 km/year) is consistent with light local commuter use and pristine condition.","detailKm":"ចម្ងាយ ៣,២០០ គ.ម ក្នុងរយៈពេល ២ ឆ្នាំ (~១,៦០០ គ.ម/ឆ្នាំ) សមរម្យសម្រាប់ការជិះក្បែរៗផ្ទះ និងត្រូវនឹងសភាពថ្មី។","source":"Listing data + age analysis","confidence":0.75},{"area":"price","title":"Price vs market","titleKm":"តម្លៃធៀបទីផ្សារ","status":"EVIDENCE_FOUND","detail":"$2,650 is within typical market range for 2023 Honda Dream 125 NCX in Phnom Penh ($2,500-$2,800).","detailKm":"២,៦៥០ ដុល្លាស្ថិតក្នុងកម្រិតតម្លៃទីផ្សារធម្មតាសម្រាប់ Honda Dream 125 ឆ្នាំ២០២៣ នៅភ្នំពេញ (២,៥០០–២,៨០០ ដុល្លា)។","source":"Market comparables","confidence":0.8},{"area":"service","title":"Service history","titleKm":"ប្រវត្តិថែទាំ","status":"EVIDENCE_FOUND","detail":"Initial 1,000 km authorized NCX warranty service recorded.","detailKm":"មានកំណត់ត្រាថែទាំដំបូង ១,០០០ គ.ម តាមការធានារបស់ NCX។","source":"Service records","confidence":0.75},{"area":"photos","title":"Photos vs description","titleKm":"រូបភាពធៀបការប្រកាស","status":"EVIDENCE_FOUND","detail":"Photos show original gold stripes, unscratched fairings, and undamaged exhaust cover.","detailKm":"រូបភាពបង្ហាញឆ្នូតមាសហ្ស៊ីន គ្មានស្នាមឆ្កូត និងគម្របស៊ីមាំងស្អាតល្អ។","source":"Listing photo analysis","confidence":0.75},{"area":"ownership","title":"Ownership history","titleKm":"ប្រវត្តិម្ចាស់ភាព","status":"EVIDENCE_FOUND","detail":"First-hand registered owner declared, consistent with registration card.","detailKm":"ម្ចាស់ដើមផ្ទាល់ដៃទី១ ត្រូវនឹងព័ត៌មានលើកាតគ្រី។","source":"Registration card","confidence":0.85},{"area":"accident","title":"Accident records","titleKm":"កំណត់ហេតុគ្រោះថ្នាក់","status":"NOT_VERIFIED","detail":"Seller declares no fall or collision history. Handlebar and mirrors appear straight in photos.","detailKm":"ម្ចាស់លក់ប្រកាសថាមិនដែលដួល ឬបុក។ ចង្កូត និងកញ្ចក់មើលក្រោយត្រង់ស្អាតក្នុងរូបភាព។","source":"Seller declaration","confidence":0.5},{"area":"listing","title":"Listing quality & safety","titleKm":"គុណភាពបញ្ជី និងសុវត្ថិភាព","status":"EVIDENCE_FOUND","detail":"Listing text is clear with authentic local details. No scam patterns detected.","detailKm":"ខ្លឹមសារផ្សព្វផ្សាយច្បាស់លាស់ គ្មានគំរូបញ្ឆោតទេ។","source":"Listing text scan","confidence":0.75}]', 84.0, 'This 2023 Honda Dream 125 NCX is in excellent standing: registration card verified, 3,200 km odometer is highly consistent with light city use, and dealer origin is platform-supported. Unverified seller fall declaration, but overall very high confidence.', 'ម៉ូតូ Honda Dream 125 ឆ្នាំ២០២៣ នេះស្ថិតក្នុងស្ថានភាពល្អបំផុត៖ កាតគ្រីបានផ្ទៀងផ្ទាត់ ចម្ងាយ ៣,២០០ គ.ម សមរម្យសម្រាប់ការជិះក្នុងក្រុង ហើយមានប្រភពចែកចាយច្បាស់លាស់។ ការប្រកាសមិនដែលដួលជាការប្រកាសរបស់ម្ចាស់លក់ ប៉ុន្តែជារួមមានទំនុកចិត្តខ្ពស់។', '[{"en":"This report analyzes motorcycle listing details, registration card, and engine checks. It is not a roadside mechanical inspection.","km":"របាយការណ៍នេះវិភាគលើព័ត៌មានលម្អិតនៃម៉ូតូ កាតគ្រី និងទិន្នន័យម៉ាស៊ីន។ វាមិនមែនជាការតេស្តបើកបរលើផ្លូវទេ។"},{"en":"''No records found'' does not guarantee absence of hidden frame bending or internal engine wear.","km":"''រកមិនឃើញទិន្នន័យ'' មិនធានាថាគ្មានបញ្ហាតួវៀច ឬការសឹកខាងក្នុងម៉ាស៊ីននោះទេ។"},{"en":"Always verify the motorcycle frame and engine numbers directly against the physical registration card.","km":"សូមផ្ទៀងផ្ទាត់លេខតួ និងលេខម៉ាស៊ីនម៉ូតូផ្ទាល់ជាមួយកាតគ្រីច្បាប់ដើមជានិច្ច។"}]', 'COMPLETE', NULL, to_timestamp(1792840768070 / 1000.0)) ON CONFLICT (id) DO UPDATE SET "vehicle_id" = EXCLUDED."vehicle_id", "checks_json" = EXCLUDED."checks_json", "overall_confidence" = EXCLUDED."overall_confidence", "summary_en" = EXCLUDED."summary_en", "summary_km" = EXCLUDED."summary_km", "limitations_json" = EXCLUDED."limitations_json", "status" = EXCLUDED."status", "requested_by" = EXCLUDED."requested_by", "created_at" = EXCLUDED."created_at";
INSERT INTO vehicle_history_reports ("id", "vehicle_id", "checks_json", "overall_confidence", "summary_en", "summary_km", "limitations_json", "status", "requested_by", "created_at") VALUES ('cmvnqjkuf003gm6utpen6gres', 'part_toyota_brake_pads', '[{"area":"identity","title":"VIN & identity","titleKm":"អត្តសញ្ញាណ និងលេខសំគាល់","status":"EVIDENCE_FOUND","detail":"OEM Part Number 04465-47060 verified with Toyota Prius and Corolla compatibility catalog.","detailKm":"លេខកូដ OEM 04465-47060 បានផ្ទៀងផ្ទាត់ជាមួយកាតាឡុកត្រូវគ្នានៃ Toyota Prius និង Corolla។","source":"OEM manufacturer catalog","confidence":0.9},{"area":"registration","title":"Registration book","titleKm":"សៀវភៅចុះបញ្ជី","status":"VERIFIED","detail":"Authorized distributor purchase invoice provided and verified by the platform.","detailKm":"វិក្កយបត្រទិញពីតំណាងចែកចាយផ្លូវការត្រូវបានផ្ដល់ជូន និងបានផ្ទៀងផ្ទាត់ដោយវេទិកា។","source":"Purchase invoice (platform-verified)","confidence":0.95},{"area":"import","title":"Import origin","titleKm":"ប្រភពនាំចូល","status":"VERIFIED","detail":"Import declaration and customs tax clearance verified from Japan.","detailKm":"លិខិតប្រកាសនាំចូល និងពន្ធគយពីប្រទេសជប៉ុនត្រូវបានផ្ទៀងផ្ទាត់។","source":"Customs declaration (platform-verified)","confidence":0.9},{"area":"mileage","title":"Odometer & mileage","titleKm":"ចំនួនគីឡូម៉ែត្រ","status":"EVIDENCE_FOUND","detail":"Declared BRAND NEW in original factory box with unbroken seal clips.","detailKm":"ប្រកាសជាទំនិញថ្មីសុទ្ធ ១០០% ក្នុងប្រអប់ដើម មានតែមបិទជិត។","source":"Packaging verification","confidence":0.85},{"area":"price","title":"Price vs market","titleKm":"តម្លៃធៀបទីផ្សារ","status":"EVIDENCE_FOUND","detail":"$38 asking price is within the standard range for authentic Toyota ceramic brake pads ($35-$45).","detailKm":"តម្លៃ ៣៨ ដុល្លាស្ថិតក្នុងកម្រិតទីផ្សារស្តង់ដារសម្រាប់ស្បែកហ្វ្រាំងសេរ៉ាមិច Toyota សុទ្ធ (៣៥–៤៥ ដុល្លា)។","source":"Market comparables","confidence":0.85},{"area":"service","title":"Service history","titleKm":"ប្រវត្តិថែទាំ","status":"EVIDENCE_FOUND","detail":"Manufacturer quality test cert and warranty against squeal included.","detailKm":"មានវិញ្ញាបនបត្រតេស្តគុណភាពរោងចក្រ និងការធានាមិនស៊ីឌីស។","source":"Warranty documentation","confidence":0.8},{"area":"photos","title":"Photos vs description","titleKm":"រូបភាពធៀបការប្រកាស","status":"EVIDENCE_FOUND","detail":"Clear photos of Toyota holographic security label and barcode serial number.","detailKm":"រូបភាពច្បាស់នៃតែមសន្តិសុខ 7 ពណ៌ Toyota និងលេខបាកូដសម្គាល់។","source":"Listing photo analysis","confidence":0.8},{"area":"ownership","title":"Ownership history","titleKm":"ប្រវត្តិម្ចាស់ភាព","status":"EVIDENCE_FOUND","detail":"Sold by verified auto parts dealership (Sokha Chea Auto Parts).","detailKm":"លក់ដោយហាងគ្រឿងបន្លាស់ដែលបានផ្ទៀងផ្ទាត់ដោយវេទិកា (Sokha Chea Auto Parts)។","source":"Merchant verification","confidence":0.85},{"area":"accident","title":"Accident records","titleKm":"កំណត់ហេតុគ្រោះថ្នាក់","status":"NOT_VERIFIED","detail":"Seller declares brand-new zero-defect item with intact ceramic friction material.","detailKm":"ម្ចាស់លក់ប្រកាសជាទំនិញថ្មីគ្មានការខូចខាត ឬប្រេះស្រាំ។","source":"Seller declaration","confidence":0.5},{"area":"listing","title":"Listing quality & safety","titleKm":"គុណភាពបញ្ជី និងសុវត្ថិភាព","status":"EVIDENCE_FOUND","detail":"Authentic OEM specifications declared. No counterfeit or scam phrasing detected.","detailKm":"លក្ខណៈបច្ចេកទេស OEM សុទ្ធ គ្មានពាក្យសម្គាល់ទំនិញក្លែងក្លាយទេ។","source":"Listing text scan","confidence":0.8}]', 88.0, 'Authentic Toyota genuine brake pads verified by authorized distributor purchase invoice and Japan customs clearance. OEM part number 04465-47060 matches Prius/Corolla catalogs. Asking price $38 aligns with market median.', 'ស្បែកហ្វ្រាំង Toyota សុទ្ធត្រូវបានផ្ទៀងផ្ទាត់ដោយវិក្កយបត្រទិញពីតំណាងចែកចាយ និងឯកសារពន្ធគយពីជប៉ុន។ លេខកូដ OEM 04465-47060 ត្រូវនឹងកាតាឡុក Prius/Corolla។ តម្លៃ ៣៨ ដុល្លាស្ថិតក្នុងកម្រិតទីផ្សារធម្មតា។', '[{"en":"This report evaluates part OEM numbers, compatibility fitment, and market pricing. It is not a bench test or metallurgical inspection.","km":"របាយការណ៍នេះវាយតម្លៃលេខកូដគ្រឿងបន្លាស់ ម៉ូដែលត្រូវគ្នា និងតម្លៃទីផ្សារ។ វាមិនមែនជាការតេស្តមន្ទីរពិសោធន៍ទេ។"},{"en":"''Brand new'' condition reflects seller declaration; inspect packaging seals, manufacturer labels, and serial barcodes upon delivery.","km":"ការប្រកាសជា ''ទំនិញថ្មី'' ផ្អែកលើការបញ្ជាក់របស់អ្នកលក់។ សូមពិនិត្យតែមប្រអប់ ស្លាករោងចក្រ និងបាកូដពេលទទួល។"},{"en":"Always verify exact part number fitment with your professional mechanic before unboxing or installation.","km":"សូមបញ្ជាក់លេខកូដគ្រឿងបន្លាស់ និងភាពត្រូវគ្នាជាមួយជាងជំនាញរបស់អ្នក មុនពេលធ្វើការតម្លើង។"}]', 'COMPLETE', NULL, to_timestamp(1792840768071 / 1000.0)) ON CONFLICT (id) DO UPDATE SET "vehicle_id" = EXCLUDED."vehicle_id", "checks_json" = EXCLUDED."checks_json", "overall_confidence" = EXCLUDED."overall_confidence", "summary_en" = EXCLUDED."summary_en", "summary_km" = EXCLUDED."summary_km", "limitations_json" = EXCLUDED."limitations_json", "status" = EXCLUDED."status", "requested_by" = EXCLUDED."requested_by", "created_at" = EXCLUDED."created_at";
INSERT INTO vehicle_history_reports ("id", "vehicle_id", "checks_json", "overall_confidence", "summary_en", "summary_km", "limitations_json", "status", "requested_by", "created_at") VALUES ('cmvnqvwd80003lq01dna5lvg7', 'veh_honda_scoopy_2024', '[{"area":"identity","title":"Motorcycle identity","titleKm":"អត្តសញ្ញាណម៉ូតូ","status":"NOT_VERIFIED","detail":"Motorcycle identifiers present (Plate 1KC-1234, 110cc). Cross-verify with motorcycle card (កាតគ្រី).","detailKm":"មានព័ត៌មានអត្តសញ្ញាណម៉ូតូ (ស្លាកលេខ 1KC-1234, កម្លាំង 110cc)។ សូមផ្ទៀងផ្ទាត់ជាមួយកាតគ្រីម៉ូតូ។","source":"Listing data","confidence":0.55},{"area":"registration","title":"Motorcycle card (កាតគ្រី)","titleKm":"កាតគ្រីម៉ូតូ","status":"VERIFIED","detail":"Motorcycle registration card (កាតគ្រីម៉ូតូ) provided and verified by the platform.","detailKm":"កាតគ្រីម៉ូតូត្រូវបានផ្ដល់ជូន និងបានផ្ទៀងផ្ទាត់ដោយវេទិកាហើយ។","source":"Motorcycle card (platform-verified)","confidence":0.95},{"area":"import","title":"Customs & import tax","titleKm":"ឯកសារពន្ធគយម៉ូតូ","status":"NO_DATA","detail":"No import customs document provided. Common for locally registered bikes.","detailKm":"គ្មានឯកសារពន្ធគយផ្ដល់ជូនទេ។ ជារឿងធម្មតាសម្រាប់ម៉ូតូចុះបញ្ជីក្នុងស្រុករួច។","source":"Customs declaration","confidence":0.05},{"area":"mileage","title":"Motorcycle mileage","titleKm":"ភាពសមរម្យនៃចម្ងាយដំណើរម៉ូតូ","status":"INCONSISTENT","detail":"Very low annual motorcycle mileage (1,500 km/year) — check tire tread, brake wear and odometer integrity.","detailKm":"ចម្ងាយដំណើរប្រចាំឆ្នាំតិចខុសប្រក្រតី (1,500 គ.ម/ឆ្នាំ) — សូមពិនិត្យក្រឡាកង់ កម្រាស់ហ្វ្រាំង និងកុងទ័រ។","source":"Listing data + age analysis","confidence":0.4},{"area":"price","title":"Price vs. motor market","titleKm":"តម្លៃធៀបនឹងទីផ្សារម៉ូតូ","status":"NO_DATA","detail":"Not enough comparable motorcycle listings to assess price.","detailKm":"បញ្ជីលក់ម៉ូតូស្រដៀងគ្នាមិនគ្រប់គ្រាន់ ដើម្បីវាយតម្លៃតម្លៃនេះទេ។","source":"Market comparables","confidence":0.1},{"area":"service","title":"Maintenance records","titleKm":"បញ្ជីការថែទាំនិងប្តូរប្រេង","status":"NO_DATA","detail":"No maintenance records provided. Inquire about recent oil, belt/chain and tire changes.","detailKm":"គ្មានបញ្ជីថែទាំផ្ដល់ជូនទេ។ សូមសួរពីការប្តូរប្រេង ខ្សែពាន/ច្រវាក់ និងសម្បកកង់ថ្មីៗ។","source":"Service records","confidence":0.05},{"area":"photos","title":"Motorcycle photos","titleKm":"រូបភាពម៉ូតូ","status":"NOT_VERIFIED","detail":"Only 1 photo(s). Request clear photos of engine block, odometer, and both sides.","detailKm":"មានរូបភាពតែ 1 រូបប៉ុណ្ណោះ។ សូមសុំរូបថតច្បាស់នៃម៉ាស៊ីន កុងទ័រ និងសងខាងម៉ូតូ។","source":"Listing photos","confidence":0.35},{"area":"ownership","title":"Ownership history","titleKm":"ប្រវត្តិម្ចាស់ម៉ូតូ","status":"NO_DATA","detail":"Ownership history unknown.","detailKm":"ប្រវត្តិម្ចាស់មិនដឹងច្បាស់។","source":"Listing data","confidence":0.05},{"area":"accident","title":"Fall & accident declaration","titleKm":"ប្រវត្តិគ្រោះថ្នាក់ឬដួល","status":"NO_DATA","detail":"No accident or fall history declared. Treat as unknown.","detailKm":"គ្មានព័ត៌មានគ្រោះថ្នាក់ ឬដួលប្រកាសទេ។ សូមចាត់ទុកថាមិនទាន់ដឹង។","source":"Seller declaration","confidence":0.05},{"area":"listing","title":"Listing content","titleKm":"ខ្លឹមសារការផ្សព្វផ្សាយ","status":"EVIDENCE_FOUND","detail":"Listing text scan found no common motorcycle scam patterns.","detailKm":"ការវិភាគអត្ថបទបញ្ជាលក់មិនរកឃើញគំរូបញ្ឆោតធម្មតាទេ។","source":"Listing text analysis","confidence":0.7}]', 35.0, 'Based on 10 evidence checks for this motorcycle: 1 verified, 1 supported by evidence, 1 inconsistencies flagged, 2 unverified, 5 with no data. Key items to verify in person or with seller: Customs & import tax, Motorcycle mileage, Price vs. motor market.', 'ផ្អែកលើការវិភាគភស្តុតាង 10 ចំណុច៖ 1 ចំណុចបានផ្ទៀងផ្ទាត់, 1 ចំណុចមានភស្ដុតាងគាំទ្រ, 1 ចំណុចមានភាពមិនសមស្រប, 2 ចំណុចមិនទាន់ផ្ទៀងផ្ទាត់, 5 ចំណុចគ្មានទិន្នន័យ។ ចំណុចសំខាន់ៗដែលត្រូវពិនិត្យដោយផ្ទាល់ ឬផ្ទៀងផ្ទាត់ជាមួយអ្នកលក់៖ ឯកសារពន្ធគយម៉ូតូ, ភាពសមរម្យនៃចម្ងាយដំណើរម៉ូតូ, តម្លៃធៀបនឹងទីផ្សារម៉ូតូ។', '[{"en":"This report analyzes motorcycle listing details, registration card, and engine checks. It is not a roadside mechanical inspection.","km":"របាយការណ៍នេះវិភាគលើព័ត៌មានលម្អិតនៃម៉ូតូ កាតគ្រី និងទិន្នន័យម៉ាស៊ីន។ វាមិនមែនជាការតេស្តបើកបរលើផ្លូវទេ។"},{"en":"''No records found'' does not guarantee absence of hidden frame bending or internal engine wear.","km":"''រកមិនឃើញទិន្នន័យ'' មិនធានាថាគ្មានបញ្ហាតួវៀច ឬការសឹកខាងក្នុងម៉ាស៊ីននោះទេ។"},{"en":"Always verify the motorcycle frame and engine numbers directly against the physical registration card.","km":"សូមផ្ទៀងផ្ទាត់លេខតួ និងលេខម៉ាស៊ីនម៉ូតូផ្ទាល់ជាមួយកាតគ្រីច្បាប់ដើមជានិច្ច។"}]', 'COMPLETE', 'usr_demo_buyer', to_timestamp(1792927742876 / 1000.0)) ON CONFLICT (id) DO UPDATE SET "vehicle_id" = EXCLUDED."vehicle_id", "checks_json" = EXCLUDED."checks_json", "overall_confidence" = EXCLUDED."overall_confidence", "summary_en" = EXCLUDED."summary_en", "summary_km" = EXCLUDED."summary_km", "limitations_json" = EXCLUDED."limitations_json", "status" = EXCLUDED."status", "requested_by" = EXCLUDED."requested_by", "created_at" = EXCLUDED."created_at";
INSERT INTO vehicle_history_reports ("id", "vehicle_id", "checks_json", "overall_confidence", "summary_en", "summary_km", "limitations_json", "status", "requested_by", "created_at") VALUES ('cmvnqw2uf0005lq01qh1v088j', 'part_prius_hybrid_battery', '[{"area":"identity","title":"Part number & fitment","titleKm":"លេខកូដគ្រឿងបន្លាស់និងភាពត្រូវគ្នា","status":"EVIDENCE_FOUND","detail":"Part identity established with manufacturer/OEM part number (G9510-47031) and compatibility list (Toyota Prius 2004-2009 (Gen 2), Prius 2010-2015 (Gen 3)).","detailKm":"អត្តសញ្ញាណគ្រឿងបន្លាស់ត្រូវបានបញ្ជាក់ជាមួយលេខកូដ OEM (G9510-47031) និងបញ្ជីម៉ូដែលត្រូវគ្នា (Toyota Prius 2004-2009 (Gen 2), Prius 2010-2015 (Gen 3))។","source":"OEM part data","confidence":0.85},{"area":"registration","title":"Invoice & purchase receipt","titleKm":"វិក្កយបត្រទិញនិងបង្កាន់ដៃ","status":"VERIFIED","detail":"Authorized distributor receipt / tax invoice provided and verified by the platform.","detailKm":"វិក្កយបត្រទិញពីតំណាងចែកចាយ ឬវិក្កយបត្រផ្លូវការត្រូវបានផ្ដល់ជូន និងបានផ្ទៀងផ្ទាត់ដោយវេទិកាហើយ។","source":"Purchase invoice (platform-verified)","confidence":0.95},{"area":"import","title":"Origin & distributor seal","titleKm":"ប្រភពដើមនិងតែមចែកចាយ","status":"NO_DATA","detail":"No origin or distributor import declaration provided.","detailKm":"គ្មានសេចក្ដីប្រកាសប្រភពដើម ឬឯកសារនាំចូលផ្ដល់ជូនទេ។","source":"Distributor declaration","confidence":0.1},{"area":"mileage","title":"Condition & wear status","titleKm":"ស្ថានភាពនិងកម្រិតប្រើប្រាស់","status":"EVIDENCE_FOUND","detail":"Declared as USED GENUINE (OEM salvaged/take-off). Inspect for structural wear, crack lines, and remaining lifespan.","detailKm":"ប្រកាសជាគ្រឿងបន្លាស់ហ្ស៊ីនមួយទឹក (Used Genuine)។ សូមពិនិត្យភាពសឹករិចរិល ស្នាមប្រេះ និងកម្រាស់ប្រើប្រាស់ដែលនៅសល់។","source":"Part condition analysis","confidence":0.65},{"area":"price","title":"Price vs. part market","titleKm":"តម្លៃធៀបនឹងទីផ្សារគ្រឿងបន្លាស់","status":"NO_DATA","detail":"Not enough comparable spare part listings to assess price.","detailKm":"បញ្ជីលក់គ្រឿងបន្លាស់ស្រដៀងគ្នាមិនគ្រប់គ្រាន់ ដើម្បីវាយតម្លៃតម្លៃនេះទេ។","source":"Market comparables","confidence":0.1},{"area":"service","title":"Warranty & test cert","titleKm":"ការធានានិងវិញ្ញាបនបត្រតេស្ត","status":"VERIFIED","detail":"Manufacturer/distributor warranty card or test bench certification verified.","detailKm":"ប័ណ្ណធានារបស់រោងចក្រ/តំណាងចែកចាយ ឬវិញ្ញាបនបត្រតេស្តគុណភាពត្រូវបានផ្ទៀងផ្ទាត់ហើយ។","source":"Warranty card (platform-verified)","confidence":0.9},{"area":"photos","title":"Part & label photos","titleKm":"រូបភាពគ្រឿងបន្លាស់និងស្លាកកូដ","status":"NOT_VERIFIED","detail":"Only 1 photo(s). Request close-up photos of manufacturer stamp, barcode, and wear surfaces.","detailKm":"មានរូបភាពតែ 1 រូបប៉ុណ្ណោះ។ សូមសុំរូបថតជិតនៃត្រាកូដ បាកូដ និងផ្ទៃសឹក។","source":"Listing photos","confidence":0.35},{"area":"ownership","title":"Supplier credibility","titleKm":"ភាពគួរឱ្យទុកចិត្តនៃអ្នកផ្គត់ផ្គង់","status":"EVIDENCE_FOUND","detail":"Sold by a platform-verified merchant or authorized dealer (Sokha Motors).","detailKm":"លក់ដោយអាជីវកម្ម ឬតំណាងចែកចាយដែលបានផ្ទៀងផ្ទាត់ដោយវេទិកា (Sokha Motors)។","source":"Merchant verification","confidence":0.75},{"area":"accident","title":"Defect & refurbished declaration","titleKm":"សេចក្តីប្រកាសបញ្ហានិងការខូចខាត","status":"NO_DATA","detail":"No defect declaration provided. Confirm fitment and return guarantee with seller.","detailKm":"គ្មានសេចក្ដីប្រកាសពីបញ្ហាគ្រឿងបន្លាស់ទេ។ សូមបញ្ជាក់ភាពត្រូវគ្នា និងការធានាប្តូរជាមួយម្ចាស់លក់។","source":"Seller declaration","confidence":0.1},{"area":"listing","title":"Listing & authenticity scan","titleKm":"ខ្លឹមសារការផ្សព្វផ្សាយនិងការស្កេន","status":"EVIDENCE_FOUND","detail":"Listing text scan found no counterfeit or scam patterns.","detailKm":"ការវិភាគអត្ថបទបញ្ជាលក់មិនរកឃើញគំរូទំនិញក្លែងក្លាយ ឬបញ្ឆោតទេ។","source":"Listing text scan","confidence":0.7}]', 58.0, 'Based on 10 evidence checks for this part: 2 verified, 4 supported by evidence, 0 inconsistencies flagged, 1 unverified, 3 with no data. Key items to verify in person or with seller: Origin & distributor seal, Price vs. part market, Defect & refurbished declaration.', 'ផ្អែកលើការវិភាគភស្តុតាង 10 ចំណុច៖ 2 ចំណុចបានផ្ទៀងផ្ទាត់, 4 ចំណុចមានភស្ដុតាងគាំទ្រ, 0 ចំណុចមានភាពមិនសមស្រប, 1 ចំណុចមិនទាន់ផ្ទៀងផ្ទាត់, 3 ចំណុចគ្មានទិន្នន័យ។ ចំណុចសំខាន់ៗដែលត្រូវពិនិត្យដោយផ្ទាល់ ឬផ្ទៀងផ្ទាត់ជាមួយអ្នកលក់៖ ប្រភពដើមនិងតែមចែកចាយ, តម្លៃធៀបនឹងទីផ្សារគ្រឿងបន្លាស់, សេចក្តីប្រកាសបញ្ហានិងការខូចខាត។', '[{"en":"This report evaluates part OEM numbers, compatibility fitment, and market pricing. It is not a bench test or metallurgical inspection.","km":"របាយការណ៍នេះវាយតម្លៃលេខកូដគ្រឿងបន្លាស់ ម៉ូដែលត្រូវគ្នា និងតម្លៃទីផ្សារ។ វាមិនមែនជាការតេស្តមន្ទីរពិសោធន៍ទេ។"},{"en":"''Brand new'' condition reflects seller declaration; inspect packaging seals, manufacturer labels, and serial barcodes upon delivery.","km":"ការប្រកាសជា ''ទំនិញថ្មី'' ផ្អែកលើការបញ្ជាក់របស់អ្នកលក់។ សូមពិនិត្យតែមប្រអប់ ស្លាករោងចក្រ និងបាកូដពេលទទួល។"},{"en":"Always verify exact part number fitment with your professional mechanic before unboxing or installation.","km":"សូមបញ្ជាក់លេខកូដគ្រឿងបន្លាស់ និងភាពត្រូវគ្នាជាមួយជាងជំនាញរបស់អ្នក មុនពេលធ្វើការតម្លើង។"}]', 'COMPLETE', 'usr_demo_buyer', to_timestamp(1792927751272 / 1000.0)) ON CONFLICT (id) DO UPDATE SET "vehicle_id" = EXCLUDED."vehicle_id", "checks_json" = EXCLUDED."checks_json", "overall_confidence" = EXCLUDED."overall_confidence", "summary_en" = EXCLUDED."summary_en", "summary_km" = EXCLUDED."summary_km", "limitations_json" = EXCLUDED."limitations_json", "status" = EXCLUDED."status", "requested_by" = EXCLUDED."requested_by", "created_at" = EXCLUDED."created_at";
