INSERT INTO platform_settings ("key", "value_json", "updated_at") VALUES ('payments.manualConfig', '{"enabled":true,"accountName":"KhLan Payments (Sokha Chan)","khqrPayload":null,"khqrImageUrl":null,"instructionsEn":"1. Scan the KHQR with your banking app\n2. Transfer the exact USD amount\n3. Include the payment reference in the transfer note\n4. Send your transaction reference to the admin on Telegram\n5. The admin verifies and activates your subscription","instructionsKm":"១. ស្កេន KHQR ដោយកម្មវិធីធនាគាររបស់អ្នក\n២. បញ្ជូនចំនួនត្រឹមត្រូវជាដុល្លារ\n៣. ដាក់លេខយោងក្នុងកំណត់សម្គាល់បញ្ជូន\n៤. ផ្ញើលេខយោងប្រតិបត្តិការធនាគារទៅអ្នកគ្រប់គ្រងតាម Telegram\n៥. អ្នកគ្រប់គ្រងផ្ទៀងផ្ទាត់ និងដំណើរការការជាវរបស់អ្នក","telegram":"@khlan_admin","freePlan":{"enabled":true,"listingsLimit":3,"featuredLimit":0,"seats":1}}', to_timestamp(1792927168075 / 1000.0)) ON CONFLICT (key) DO UPDATE SET "value_json" = EXCLUDED."value_json", "updated_at" = EXCLUDED."updated_at";
