INSERT INTO messages ("id", "conversation_id", "sender_id", "body", "is_system", "created_at") VALUES ('cmvnqjkug003hm6ut2tx7au6y', 'conv_demo_1', NULL, 'គន្លឹះសុវត្ថិភាព: កុំបង់ប្រាក់ដុនមុនពេលមើលឡាននិងឯកសារ។ ជួបកន្លែងមានគេច្រើន ហើយនាំគ្រូបង្គោលមកពិនិត្យជាមួយ។ / Safety tip: Never pay a deposit before seeing the car and documents. Meet in a public place and bring a trusted mechanic.', TRUE, to_timestamp(1792757968072 / 1000.0)) ON CONFLICT (id) DO NOTHING;
INSERT INTO messages ("id", "conversation_id", "sender_id", "body", "is_system", "created_at") VALUES ('cmvnqjkug003im6utr10c1buz', 'conv_demo_1', 'usr_demo_buyer', 'សួស្តី ឡាននៅមានទេ? ចង់ដឹងថាអាចមកមើលថ្ងៃសៅរ៍បានទេ? / Hello, is the car still available? Can I come see it Saturday?', FALSE, to_timestamp(1792833568072 / 1000.0)) ON CONFLICT (id) DO NOTHING;
INSERT INTO messages ("id", "conversation_id", "sender_id", "body", "is_system", "created_at") VALUES ('cmvnqjkug003jm6ut7kkf6pg5', 'conv_demo_1', 'usr_dealer_sokha', 'សួស្តី! ឡាននៅមាន។ សូមកោះមកមើលនៅផ្លូវព្រះនុហុង ៨ព្រឹក ដល់ ៦ល្ងាច។ / Hello! Yes, still available. You''re welcome to view it on Preah Norodom Blvd, 8am–6pm any day.', FALSE, to_timestamp(1792855168072 / 1000.0)) ON CONFLICT (id) DO NOTHING;
